    "description": "宝宝近来虽然课程当中有关于数独的类似游戏，但单独去做纯数字的数独还是不感兴趣，有时候几天做一次，有时候想起来做两个，今天让他做又觉得有些勉强，得想办法呀，于是看到上面有计时的，就用手机进行倒计时，掐时间看，越快越好，这一招还真管用，宝宝总想力争上游，于是在做数独数字的时候总想得越快越好，而且总是在提前心算好之后开始进行计时，果然有不到一分钟、半分钟逐步的进行了速度的提升，而且准确率也达到了100%。一开始说自己做一道题，后来又说做6道题…",
