    "content": "新华社北京9月26日电（记者樊曦）记者26日从中铁十八局集团有限公司了解到，在娄底梅山灌区核心控制性工程渠首隧洞建设现场，湖南首台水利项目全断面隧道掘进机（TBM）“梅山蛮号”累计掘进突破5000米大关，标志着TBM智能化掘进技术在湖南水利领域的规模化应用取得阶段性进展。 梅山灌区工程是国家“十四五”水安全保障规划重大水利工程，也是娄底市单体投资规模最大的民生水利项目。工程构建“长藤结瓜”水资源调配体系，串联区域内191座中小型水库，建成后年新增供水量1.37亿立方米，将进一步提升区域灌溉和城乡供水保障能力。 本次…"
