    "content": "快科技9月26日消息， 近期，在海南海口举办的2026世界新能源汽车大会上，比亚迪集团首席科学家、汽车工程研究院院长廉玉波分享了企业对行业发展的判断，同时对外公布了规模宏大的补能网络建设规划。 廉玉波在演讲中提出，电动化依旧是新能源汽车发展的核心根基，行业在持续深耕电动化技术的同时，还需要推进汽车智能化升级，以此匹配消费者多样化的用车需求，进一步改善新能源汽车的使用体验。 依托第二代刀片电池、整车制造、光伏充电桩以及储能设备，比亚迪已经搭建起完整的产业链条，为大规模铺开充电网络打下技术基础。 按照规划，比亚迪准备在…"
