    "content": "新华社日本名古屋9月26日电（记者李子越）爱知·名古屋亚运会官网26日消息，本届亚运会组委会事务总长村手聪就近期接连出现的赛事组织问题表示道歉。 为压缩成本，本届赛事安排运动员居住在邮轮、集装箱房和各地酒店，住宿条件引发争议。赛会提供的交通保障也多次出现问题。 针对此类后勤保障问题，村手说，赛事期间确实出现了一些差错，原因有多方面，“但无论是什么原因，提供这些服务都是组委会的责任，因此我要坦率地为这些失误道歉”。 谈及问题产生的原因，村手表示，赛事工作人员缺乏大型国际赛事运营经验是因素之一。他说，日本通常在某一城市…"
