    "content": "破产制度是现代市场经济不可或缺的基础制度。 中国加入WTO后，第一部适用于市场经济的中国《企业破产法》于2006年颁布，2007年实施。时隔近20年，2025年9月，全国人大常委会第十七次会议对企业破产法修订草案（以下简称“一审稿”）进行初次审议，征求意见并修订后，形成此二审稿。2026年8月25日，《企业破产法》修订草案（以下简称“二审稿”）提请全国人大常委会会议二次审议。 相对一审稿的“大修”，二审稿以“小改”为主，主要 涉及 ：完善连带个人债务人破产规则、增设重整前协商制度、完善管理人制度、完善跨境破产规则、…"
