    "content": "9月25日9时52分，知名歌手刘欢在家人的陪伴下于上海病逝，享年63岁。 除了知名歌手，刘欢还有一个重要身份，那就是对外经济贸易大学教师。他从1991年起在对外经贸大学工作，担任艺术教研室教师、副教授，2023年9月退休，在学校从事了三十余年的教学工作，其主讲的《西方音乐史》是对外经贸大学的美育经典课程。 “我这几年也知道他的身体可能不太好，但没想到这么突然。不敢相信，63岁，真的太年轻了，天妒英才啊。”9月26日，曾在1999年到2009年间担任对外经贸大学校长的陈准民接受澎湃新闻记者采访时感慨。 陈准民告诉记者…"
