    "content": "新华社日本名古屋9月26日电 题：盛李豪，还是从前那个少年 新华社记者林德韧、梁晨、刘磊 男子50米步枪三姿资格赛，打完最后一发子弹，盛李豪结束了爱知·名古屋亚运会征程。参赛5项拿到4金，他的亚运经历收获满满。 比赛结束，他笑着跟教练聊着比赛感受，然后拿起一袋面包开始“干饭”。 “收获，首先成绩是非常非常好，是超出我预期的，因为训练成绩不太好，可能这次运气好吧，比赛就发挥特别好。”总结这次亚运之旅，盛李豪这样说。 从五年前的东京初登奥运赛场，到本届亚运会的“四金王”，盛李豪不断挑战，不断成长。 然而，当被问到五年来…"
