    "title": "千年文化“上新” 数字技术打开新空间",
    "link": "http://www.news.cn/20260926/442a878b168341d0beeaf3a70ef917ea/c.html",
    "pub_date": "2026-09-26 16:59:42",
    "author": "戴锦镕,许舜达",
    "description": "一段古乐响起，光影随之流转。观众轻触装置，瑟音随即传来；随着互动变化，眼前的音乐场景也不断变换。原本只能隔着玻璃远观的古老乐器，有了可以触摸、可以聆听、可以参与的新“打开方式”。 在第五届全球数字贸易博览会上，浙江音乐学院带来的数字装置艺术吸引不少观众驻足。借助数字影像、声音、交互等技术，传统音乐文化不再只是静静陈列，而被“搬”进一个可以感知、参与和互动的数字空间。 观众正在体验曾侯乙沉浸式互动音乐展厅。新华社记者戴锦镕 摄 “我们模拟…",
