    "description": "中新网银川9月26日电 (记者 李佩珊)九月是宁夏贺兰山东麓酿酒葡萄的丰收采摘时节，产区迎来最美景致。26日，2026宁夏贺兰山东麓半程马拉松路跑双季赛(金秋赛)在银川西夏区贺兰羿射箭主题综合运动中心鸣枪开跑。本次赛事经中国田径协会B类赛事技术认证，吸引来自北京、福建、甘肃、宁夏等十余个省份的5500名选手，在葡萄园环绕的赛道追风奔跑。",
