    "content": "新华社德黑兰9月26日电（记者沙达提 陈霄）据伊朗伊斯兰共和国通讯社26日报道，伊朗外交部长阿拉格齐日前在纽约联合国总部表示，美国和以色列对伊朗的侵略已造成超过5000人丧生，其中包括数百名妇女和儿童。 阿拉格齐25日在联合国总部接受媒体采访时发表上述言论。他列举了遭袭的部分非军事目标，包括居民区、学校、医院、能源设施和交通基础设施等。 阿拉格齐说，美以针对伊朗前最高领袖阿里·哈梅内伊以及多名高级政治和军事官员的暗杀行动是公然犯罪，违反国际法。 美国和以色列2月28日对伊朗发动军事打击。作为回应，伊朗袭击了以色列境…"
