    "content": "高通 宣布 ，与苹果的全球专利许可协议自2027年4月1日起续签。高通技术许可业务（QTL）执行副总裁兼总经理John Han表示，很高兴延长了与苹果之间的许可协议。 高通没有提供新许可协议的具体条款信息，包括期限、费率及其他财务条款。高通简短的声明受到关注，与苹果推进自研基带项目有关。考虑到声明中没有提及芯片供应问题，双方的合作很有可能转向专利许可。 高通与苹果在2019年结束了持续两年的全球专利诉讼，达成和解，其中苹果向高通支付一笔费用，并签署一份自2019年4月1日起生效、为期6年的全球专利许可协议，同时签署…"
