    "title": "俄军称打击乌方“星链”运行支持数据处理中心",
    "link": "http://www.news.cn/20260926/cb65c065e512464380bcdd28efdecc4c/c.html",
    "pub_date": "2026-09-26 16:37:09",
    "author": "赵冰",
    "description": "新华社莫斯科9月26日电（记者赵冰）俄罗斯国防部26日发布通报说，25日晚至26日凌晨，俄军打击了位于乌克兰首都基辅市的一处数据处理中心，该中心为乌克兰武装部队提供移动互联网和“星链”卫星通信系统运行支持。 通报还说，俄军继续使用无人机对乌克兰港口、交通基础设施，以及乌军后勤物流和通信中心实施打击。 此外，从25日20时至26日8时，俄防空部队在阿斯特拉罕州、别尔哥罗德州、布良斯克州、沃罗涅日州等多地及黑海上空击落645架乌克兰无人机。",
    "content": "新华社莫斯科9月26日电（记者赵冰）俄罗斯国防部26日发布通报说，25日晚至26日凌晨，俄军打击了位于乌克兰首都基辅市的一处数据处理中心，该中心为乌克兰武装部队提供移动互联网和“星链”卫星通信系统运行支持。 通报还说，俄军继续使用无人机对乌克兰港口、交通基础设施，以及乌军后勤物流和通信中心实施打击。 此外，从25日20时至26日8时，俄防空部队在阿斯特拉罕州、别尔哥罗德州、布良斯克州、沃罗涅日州等多地及黑海上空击落645架乌克兰无人机。"
