    "content": "今年是中国工农红军长征胜利90周年。 重庆酉阳南腰界镇位于渝黔交界的蜿蜒群山中，这里保留有50余处红军遗址遗迹。然而关于红军在这里的故事，在酉阳以前的历史记录中不过数十字。 为了给历史记录填充“血肉”，今年64岁的退伍老兵杨胜学用了近40年时间，走遍南腰界及周边乡镇，收集整理大量珍贵史料。 2016年，语文老师何立双加入志愿讲解员队伍，整理红军故事，完善了16000多字的讲解词。他所在的南腰界镇中心小学校在2022年成立了少先队红领巾讲解团，让红军故事有了更青春的表达…… 三代人在用各自的方式讲述着红军途经南腰界时…"
