    "content": "新华社日本名古屋9月26日电（记者林德韧、梁晨）爱知·名古屋亚运会射击场26日进行了女子50米步枪三姿团体和个人项目的争夺，由王子菲、韩佳予、张力元组成的中国队打出1773环，以10环的优势强势摘得团体冠军，这也是中国代表团本届亚运会上获得的第100枚金牌。在个人赛上，韩佳予和张力元包揽金银牌。 中国队是女子50米步枪三姿团体项目的亚运会卫冕冠军。比赛开始后，三名中国队选手均展现出了不错的状态，韩佳予60枪打出594环，张力元和王子菲分别打出591环和588环，中国队以1773环的成绩完赛，距离该项目世界纪录仅差1…"
