    "content": "9月26日，中国国家主席习近平结束对美国的国事访问返回北京。 在访美行程的最后一天，习近平主席及夫人彭丽媛与特朗普总统夫妇在极具历史底蕴的红厅温馨茶叙，并获赠记录此访珍贵瞬间的纪念相册，随后一同参观《独立宣言》等美国建国纲领性文献，漫步历史。离开华盛顿时，美国政府高级官员亲赴机场送行，现场鸣放21响礼炮。前往机场途中，华侨华人和留学生代表在道路两旁挥舞中美两国国旗，热烈祝贺访问圆满成功。 回顾此次访美行程，美方以高规格礼遇迎接习近平主席的到来。访问期间，中美两国元首达成一系列共识，重申构建中美建设性战略稳定关系。两…"
