    "content": "中新社北京9月26日电 (记者 曾玥 周昕)当地时间24日，中国国家主席习近平在对美国进行国事访问期间宣布，未来5年，中方将邀请10万名美国青少年来华交流学习。接受中新社记者连线采访的美国青年表示，此举将架起连接美中两国的桥梁，期待新倡议的实施为两国青年的长久友谊打下基础。"
