    "pub_date": "2026-09-26 15:32:13",
    "author": "樊相龙",
    "description": "海报制作：樊相龙 王翔 新华社上海9月26日电（袁全 樊相龙）纤长的手指扶稳花茎，刃口斜向利落剪下，拭净花叶浮尘、注满试管清水、调整架构弧度……一套动作精准而从容。在第48届世界技能大赛花艺项目的赛场上，2004年出生的中国选手张明天，用一双布满薄茧与细碎旧伤的手，向全球观众展现了青年技能人才的细腻与匠心。 作为上海城建职业学院园林技术专业的学生，张明天是本届世赛花艺项目中国正选选手，也是来自上海的8名世赛正选选手之一。从全国职业技能大…",
    "content": "海报制作：樊相龙 王翔 新华社上海9月26日电（袁全 樊相龙）纤长的手指扶稳花茎，刃口斜向利落剪下，拭净花叶浮尘、注满试管清水、调整架构弧度……一套动作精准而从容。在第48届世界技能大赛花艺项目的赛场上，2004年出生的中国选手张明天，用一双布满薄茧与细碎旧伤的手，向全球观众展现了青年技能人才的细腻与匠心。 作为上海城建职业学院园林技术专业的学生，张明天是本届世赛花艺项目中国正选选手，也是来自上海的8名世赛正选选手之一。从全国职业技能大赛花艺项目金牌获得者，再到站上世界技能之巅，她的成长与蜕变，都深深印刻在这双终日…"
