    "content": "九十余载，烽火远去。 当年，无数红军将士浴血奋战、舍命前行。今日，山河安稳、岁月平和。 时光更迭，滚烫的红色信仰从未褪色。 回望峥嵘岁月，年轻官兵们从艰难远征中汲取力量；两代守陵人倾尽半生光阴，守护那些长眠的忠魂；归乡青年怀揣故里乡愁，以一颗初心扎根故土……他们薪火相传，接续着这片土地上生生不息的红色根脉。 从前，先辈们负重远行、以身许国；如今，我们坚守热土、续写荣光。不朽的长征精神，代代相传。 总监制：任卫东 策划：柳刚 监制：李砺寒、王逸涛 导演：刘芳 撰稿：刘芳 执行导演：李杰 摄像：王冠程、肖静、陈地杰、牟…"
