    "description": "新华社曼谷9月26日电（记者常天童）由于近48小时不间断降雨造成泰国首都曼谷大范围洪涝和交通中断，曼谷市市长差察·西迪汶26日宣布全市为洪水灾区。 西迪汶当天发布了曼谷市防灾减灾指挥部的一份声明。声明说，持续强降雨导致曼谷发生洪涝灾害，严重影响居民日常生活，可能危及生命安全并造成财产损失。因此，市政府决定宣布全市为洪水灾区，以便及时应对灾害并展开救援。 据当地媒体报道，曼谷市救灾部门正加快疏排积水并分发沙袋，并把未受洪涝影响的学校等场所…",
    "content": "新华社曼谷9月26日电（记者常天童）由于近48小时不间断降雨造成泰国首都曼谷大范围洪涝和交通中断，曼谷市市长差察·西迪汶26日宣布全市为洪水灾区。 西迪汶当天发布了曼谷市防灾减灾指挥部的一份声明。声明说，持续强降雨导致曼谷发生洪涝灾害，严重影响居民日常生活，可能危及生命安全并造成财产损失。因此，市政府决定宣布全市为洪水灾区，以便及时应对灾害并展开救援。 据当地媒体报道，曼谷市救灾部门正加快疏排积水并分发沙袋，并把未受洪涝影响的学校等场所开放为临时避难所。泰国气象部门说，25日至27日，泰国多地会出现强降雨，公众应注…"
