    "description": "特朗普政府官员已提出多项措施，以遏制柴油价格飙升，从暂停对柴油征税，到取消针对通常仅限非公路使用的红色染色柴油的销售限制。知情人士称，截至周五，相关讨论范围仍很广，许多方案仍在审议之中，短期内不会就任何潜在策略作出决定。（新浪财经）",
