    "content": "新华社联合国9月25日电 中国常驻联合国副代表孙磊25日在纽约联合国总部参加尼泊尔举办的“为气候韧性未来呼吁采取行动”高级别会议时发言，呼吁各国走绿色低碳发展道路。 他说，不久前，尼泊尔边境地区突发冰川崩塌引发严重泥石流灾害，造成中尼两国重大人员伤亡、失联。中尼山水相连、命运与共，两国都是此次跨境灾害的受灾方，彼此感同身受，对加强山地冰川保护、提升预警救灾能力有着共同诉求。中国在开展抢险自救的同时，第一时间伸出援手，派遣救援专家，分享灾区影像、卫星和水文数据等重要信息，向尼方提供紧急援助。两国人民在灾难面前，以实际…"
