    "author": "南方周末记者 梁婷 南方周末实习生 赵芸巧",
    "description": "观众每花1元钱买演唱会门票，平均能带动6.85元的其他消费。 南方周末记者 梁婷 南方周末实习生 赵芸巧 责任编辑：张玥 在太原举办的一场演唱会。太原正在打造“歌迷之城”。视觉中国/图 演唱会对经济的拉动作用有多大？看看周杰伦。 有机构对2024年5月30日至6月2日周杰伦在长沙的演唱会数据做过测算。4天演唱会，吸引15万人次入场，其中92%都是跨城来的观众，68%是跨省来的。他们在长沙平均会停留两天半。 不算演唱会门票，每个人平均会花…",
